import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '자산 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const PRINT_TYPES = ['QR', 'BARCODE'];

function isDigits(v: unknown): boolean {
  if (typeof v === 'number') {
    return Number.isInteger(v) && v > 0;
  }
  if (typeof v === 'string') {
    return /^[0-9]+$/.test(v);
  }
  return false;
}

// 가정: 외부 이미지 라이브러리가 없어 자산번호 문자 코드를 막대·칸 패턴으로 바꾼 SVG 라벨을 만든다.
function makeLabel(printType: string, assetNo: string): string {
  const cell = 6;
  const rects: string[] = [];
  let width = 0;
  let height = 60;
  if (printType === 'BARCODE') {
    let x = 10;
    for (const ch of assetNo) {
      const bits = ch.charCodeAt(0).toString(2).padStart(8, '0');
      for (const bit of bits) {
        if (bit === '1') {
          rects.push("<rect x='" + x + "' y='10' width='2' height='40' />");
        }
        x += 2;
      }
      x += 2;
    }
    width = x + 10;
  } else {
    const side = 16;
    let index = 0;
    const chars = Array.from(assetNo);
    for (let row = 0; row < side; row++) {
      for (let col = 0; col < side; col++) {
        const code = chars[index % chars.length].charCodeAt(0);
        if (((code >> (index % 8)) & 1) === 1) {
          rects.push("<rect x='" + (10 + col * cell) + "' y='" + (10 + row * cell) + "' width='" + cell + "' height='" + cell + "' />");
        }
        index++;
      }
    }
    width = side * cell + 20;
    height = side * cell + 20;
  }
  const svg = "<svg xmlns='http://www.w3.org/2000/svg' width='" + width + "' height='" + height + "'>" + rects.join('') + '</svg>';
  return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
}

@Controller('api/v1')
export class FnSfr02503Controller {
  @Post('/asset-print-logs')
  @HttpCode(200)
  async createAssetPrintLog(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const fixedAssetId = data['fixedAssetId'];
    const printType = data['printType'];
    if (!isDigits(fixedAssetId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '고정자산을 선택하세요.');
    }
    if (typeof printType !== 'string' || !PRINT_TYPES.includes(printType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '출력 유형은 QR 또는 BARCODE여야 합니다.');
    }
    return transaction(async (db) => {
      const assets = await db.query(
        'SELECT fixed_asset_id AS "fixedAssetId", asset_no AS "assetNo" FROM fixed_asset WHERE fixed_asset_id = CAST(:fixedAssetId AS bigint)',
        { fixedAssetId: String(fixedAssetId) },
      );
      if (assets.length === 0) {
        throw new ApiError(404, 'FIXED_ASSET_NOT_FOUND', '고정자산을 찾을 수 없습니다.');
      }
      const assetNo = assets[0]['assetNo'];
      if (typeof assetNo !== 'string' || assetNo.trim() === '') {
        throw new ApiError(422, 'ASSET_NO_MISSING', '자산번호가 없는 자산은 출력할 수 없습니다.');
      }
      const rows = await db.query(
        'INSERT INTO asset_print_log (fixed_asset_id, printed_by, print_type, printed_at, created_at, updated_at) ' +
          'VALUES (CAST(:fixedAssetId AS bigint), CAST(:userId AS bigint), :printType, now(), now(), now()) ' +
          'RETURNING asset_print_log_id AS "assetPrintLogId"',
        { fixedAssetId: String(fixedAssetId), userId: user.id, printType },
      );
      return {
        assetPrintLogId: Number(rows[0]['assetPrintLogId']),
        labelImage: makeLabel(printType, assetNo),
      };
    });
  }

  @Get('/asset-print-logs')
  async listAssetPrintLogs(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const rawPage = query['page'];
    const rawSize = query['size'];
    const rawAsset = query['fixedAssetId'];
    const hasValue = (v: unknown) => v !== undefined && v !== null && v !== '';
    if (hasValue(rawPage) && !isDigits(String(rawPage)) && String(rawPage) !== '0') {
      throw new ApiError(400, 'VALIDATION_FAILED', 'page 값이 올바르지 않습니다.');
    }
    if (hasValue(rawSize) && !isDigits(String(rawSize))) {
      throw new ApiError(400, 'VALIDATION_FAILED', 'size 값이 올바르지 않습니다.');
    }
    if (hasValue(rawAsset) && !isDigits(String(rawAsset))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '고정자산 값이 올바르지 않습니다.');
    }
    const page = hasValue(rawPage) ? Number(rawPage) : 0;
    const size = hasValue(rawSize) ? Math.min(Number(rawSize), MAX_SIZE) : DEFAULT_SIZE;
    const fixedAssetId = hasValue(rawAsset) ? String(rawAsset) : null;
    return transaction(async (db) => {
      const where = '(CAST(:fixedAssetId AS bigint) IS NULL OR fixed_asset_id = CAST(:fixedAssetId AS bigint))';
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM asset_print_log WHERE ' + where,
        { fixedAssetId },
      );
      const items = await db.query(
        'SELECT asset_print_log_id AS "assetPrintLogId", fixed_asset_id AS "fixedAssetId", print_type AS "printType", ' +
          'printed_by AS "printedBy", printed_at AS "printedAt" FROM asset_print_log WHERE ' + where +
          ' ORDER BY printed_at DESC, asset_print_log_id DESC LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { fixedAssetId, size: String(size), offset: String(page * size) },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }
}

