import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Tiles,
  Form,
  Field,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const PRINT_TYPE_OPTIONS: [string, string][] = [
  ['QR', 'QR'],
  ['BARCODE', '바코드'],
];

export default function FnSfr02503Page({ role, notify }: PageProps) {
  const [page, setPage] = useState(0);
  const [draftAsset, setDraftAsset] = useState<number | string>('');
  const [assetFilter, setAssetFilter] = useState<number | string>('');
  const [open, setOpen] = useState(false);
  const [fixedAssetId, setFixedAssetId] = useState<number | string>('');
  const [printType, setPrintType] = useState('');
  const [label, setLabel] = useState('');
  const size = 20;

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/asset-print-logs', role, undefined, { fixedAssetId: assetFilter, page, size }),
    [page, assetFilter, role],
  );

  const rows = data ? data.items : [];
  const total = data ? data.total : 0;

  function openDrawer() {
    setFixedAssetId('');
    setPrintType('');
    setLabel('');
    setOpen(true);
  }

  async function submit() {
    if (fixedAssetId === '' || !printType) {
      throw new Error('고정자산과 출력 유형을 선택하세요.');
    }
    const result = await call<Row>('POST', '/asset-print-logs', role, { fixedAssetId, printType });
    setLabel(String(result['labelImage'] ?? ''));
    notify('QR·바코드 라벨을 생성하고 출력 내역을 저장했습니다.');
    reload();
  }

  function printLabel() {
    window.print();
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>출력 내역</h2>
        <Tiles items={[['전체 출력 건수', total]]} />
      </section>
      <section className="box span-8">
        <h2>라벨 출력</h2>
        <Band total={total}>
          <button type="button" onClick={openDrawer}>라벨 출력</button>
        </Band>
        <Filters
          onSearch={() => {
            setPage(0);
            setAssetFilter(draftAsset);
          }}
          onReset={() => {
            setPage(0);
            setDraftAsset('');
            setAssetFilter('');
          }}
        >
          <Field label="고정자산">
            <LookupSelect table="fixed_asset" role={role} value={draftAsset} onChange={setDraftAsset} placeholder="전체" />
          </Field>
        </Filters>
        {error ? <ErrorText text={error} /> : null}
      </section>
      <section className="box span-12">
        <h2>출력 이력</h2>
        <DataTable
          rows={rows}
          empty="출력 내역이 없습니다."
          columns={[
            { key: 'assetPrintLogId', label: 'QR·바코드 출력 내역 ID' },
            {
              key: 'fixedAssetId',
              label: '고정자산',
              render: (r: Row) => <RefName table="fixed_asset" role={role} value={r['fixedAssetId']} />,
            },
            { key: 'printType', label: '출력 유형', render: (r: Row) => <Badge value={r['printType']} /> },
            {
              key: 'printedBy',
              label: '출력자',
              render: (r: Row) => <RefName table="employee" role={role} value={r['printedBy']} />,
            },
            {
              key: 'printedAt',
              label: '출력 일시',
              render: (r: Row) => <DateText value={r['printedAt']} time />,
            },
          ]}
        />
        <Pager page={page} size={size} total={total} onPage={setPage} />
      </section>
      {open ? (
        <Drawer title="자산번호별 QR·바코드 출력" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="라벨 생성">
            <Field label="고정자산" required>
              <LookupSelect table="fixed_asset" role={role} value={fixedAssetId} onChange={setFixedAssetId} />
            </Field>
            <Field label="출력 유형" required>
              <Select value={printType} onChange={setPrintType} options={PRINT_TYPE_OPTIONS} />
            </Field>
          </Form>
          {label ? (
            <div>
              <img src={label} alt="생성된 QR·바코드 라벨" />
              <button type="button" onClick={printLabel}>출력</button>
            </div>
          ) : null}
        </Drawer>
      ) : null}
    </div>
  );
}
